	@Test
	void requestInterruptionCancelsAnActiveStatementCount() throws Exception {
		CountDownLatch repositoryCountStarted = new CountDownLatch(1);
		CountDownLatch repositoryCountInterrupted = new CountDownLatch(1);
		CountDownLatch allowRepositoryCountReturn = new CountDownLatch(1);
		CountDownLatch defaultCountStarted = new CountDownLatch(1);
		CountDownLatch countConnectionClosed = new CountDownLatch(1);
		ClearServlet servlet = new ClearServlet(5000);
		Repository repository = repositoryCountThatClearsInterrupt(repositoryCountStarted,
				repositoryCountInterrupted, allowRepositoryCountReturn, defaultCountStarted, countConnectionClosed);
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("clear", "cookie-max-age", "300"));
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/clear");
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		request.addParameter("counts", "true");
		MockHttpServletResponse response = new MockHttpServletResponse();
		CountDownLatch requestFinished = new CountDownLatch(1);
		AtomicReference<Throwable> failure = new AtomicReference<>();
		Thread requestThread = new Thread(() -> {
			try {
				servlet.service(request, response);
			} catch (Throwable thrown) {
				failure.set(thrown);
			} finally {
				requestFinished.countDown();
			}
		}, "clear-request-interruption-test");
		try {
			requestThread.start();
			assertThat(repositoryCountStarted.await(2, TimeUnit.SECONDS)).isTrue();
			requestThread.interrupt();

			assertThat(repositoryCountInterrupted.await(1, TimeUnit.SECONDS))
					.as("request interruption cancels the owned count worker")
					.isTrue();
			assertThat(requestFinished.await(1, TimeUnit.SECONDS)).isTrue();
			assertThat(failure.get()).isInstanceOf(ServletException.class);
			assertThat(failure.get().getCause()).isInstanceOf(InterruptedException.class);
		} finally {
			allowRepositoryCountReturn.countDown();
			requestThread.join(2000);
			servlet.destroy();
		}
		assertThat(countConnectionClosed.await(1, TimeUnit.SECONDS)).isTrue();
		assertThat(defaultCountStarted.getCount()).isEqualTo(1);
	}

