	private List<JsonNode> run(ClearServlet servlet, Repository repository, boolean counts) throws Exception {
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		servlet.init(TestServletConfig.withParams("clear", "cookie-max-age", "300"));
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/clear");
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			if (counts) {
				request.addParameter("counts", "true");
			}
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response.getContentAsString().lines().map(ClearServletPageDataTest::readTree).toList();
		} finally {
			servlet.destroy();
		}
	}

	/** A store whose statement sizes wait until the test ends: every size, or only the size of the given graph. */
	private Repository slowCountingStore(String slowGraph) {
		return new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public long size(Resource... contexts) throws RepositoryException {
						boolean slow = slowGraph == null || contexts.length == 1 && contexts[0] != null
								&& slowGraph.equals(contexts[0].stringValue());
						if (slow) {
							try {
								slowCounts.await(30, TimeUnit.SECONDS);
							} catch (InterruptedException e) {
								Thread.currentThread().interrupt();
							}
						}
						return super.size(contexts);
					}
				};
			}
		};
	}

	private Repository slowContextListingStore(CountDownLatch contextEnumerationStarted,
			CountDownLatch allowContextEnumeration, CountDownLatch discoveryConnectionClosed,
			CountDownLatch statementCountStarted) {
		return slowContextListingStore(contextEnumerationStarted, allowContextEnumeration,
				discoveryConnectionClosed, statementCountStarted, new CountDownLatch(0));
	}

	private Repository slowContextListingStore(CountDownLatch contextEnumerationStarted,
			CountDownLatch allowContextEnumeration, CountDownLatch discoveryConnectionClosed,
			CountDownLatch statementCountStarted, CountDownLatch contextEnumerationInterrupted) {
		return new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					@Override
					public RepositoryResult<Resource> getContextIDs() throws RepositoryException {
						contextEnumerationStarted.countDown();
						try {
							allowContextEnumeration.await();
						} catch (InterruptedException e) {
							contextEnumerationInterrupted.countDown();
							Thread.currentThread().interrupt();
						}
						return super.getContextIDs();
					}

					@Override
					public long size(Resource... contexts) throws RepositoryException {
						statementCountStarted.countDown();
						return super.size(contexts);
					}

					@Override
					public void close() throws RepositoryException {
						try {
							super.close();
						} finally {
							discoveryConnectionClosed.countDown();
						}
					}
				};
			}
		};
	}

	private Repository repositoryCountThatClearsInterrupt(CountDownLatch repositoryCountStarted,
			CountDownLatch repositoryCountInterrupted, CountDownLatch allowRepositoryCountReturn,
			CountDownLatch defaultCountStarted, CountDownLatch countConnectionClosed) {
		return new RepositoryWrapper(store) {
			@Override
			public RepositoryConnection getConnection() throws RepositoryException {
				return new RepositoryConnectionWrapper(this, super.getConnection()) {
					private final AtomicBoolean counting = new AtomicBoolean();

					@Override
					public long size(Resource... contexts) throws RepositoryException {
						counting.set(true);
						if (contexts.length == 0) {
							repositoryCountStarted.countDown();
							while (allowRepositoryCountReturn.getCount() != 0) {
								try {
									allowRepositoryCountReturn.await();
								} catch (InterruptedException e) {
									repositoryCountInterrupted.countDown();
								}
							}
						} else if (contexts.length == 1 && contexts[0] == null) {
							defaultCountStarted.countDown();
						}
						return super.size(contexts);
					}

					@Override
					public void close() throws RepositoryException {
						try {
							super.close();
						} finally {
							if (counting.get()) {
								countConnectionClosed.countDown();
							}
						}
					}
				};
			}
		};
	}

	private static JsonNode readTree(String line) {
		try {
			return JSON_MAPPER.readTree(line);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static List<String> vars(List<JsonNode> records) {
		List<String> names = new ArrayList<>();
		records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.forEach(record -> record.path("values").forEach(name -> names.add(name.asText())));
		return names;
	}

	private static JsonNode metadata(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "metadata".equals(record.path("type").asText()))
				.map(record -> record.path("values"))
				.findFirst()
				.orElse(JSON_MAPPER.createObjectNode());
	}

	private static List<String> column(List<JsonNode> records, int index) {
		List<String> values = new ArrayList<>();
		for (JsonNode record : records) {
			if ("rows".equals(record.path("type").asText())) {
				record.path("values").forEach(row -> {
					JsonNode term = row.get(index);
					values.add(term == null || term.isNull() ? null : term.path("value").asText());
				});
			}
		}
		return values;
	}
